    return (
        <>
            <Header />
            <Hero/>
            {/* <section id="home" style={{ height: "100vh", background: "#1e1e1e", color: "#fff", display: "flex", justifyContent: "center", alignItems: "center" }}>
                <h1>Welcome to My Portfolio</h1>
            </section> */}
            {/* <section id="skills" style={{ height: "100vh", background: "#111", color: "#fff" }}>
                <h1>Skills Section</h1>
            </section> */}
            <Skill/>
            <section id="projects" style={{ height: "100vh", background: "#1e1e1e", color: "#fff" }}>
